import CategoryTheory.Adjunction
import CategoryTheory.Limits.PreservesLimits
import CategoryTheory.Forget

open CategoryTheory

theorem lg_target : (CategoryTheory.forget₂ RingCat AddCommGrpCat).IsRightAdjoint := by
  let F := CategoryTheory.forget₂ RingCat AddCommGrpCat
  have preserves_limits : F.PreservesLimits := RingCat.forget₂AddCommGroup_preservesLimits
  let G : AddCommGrpCat ⥤ RingCat :=
    { obj := λ G, Ring.ofAddCommGroup G
      , map := λ G G' f, Ring.homOfAddHom f }
  let η : NaturalTransformation (functor_id AddCommGrpCat) F :=
    { app := λ G, Ring.id (Ring.ofAddCommGroup G) }
  let ε : NaturalTransformation F (functor_id RingCat) :=
    { app := λ R, Ring.homToAddHom (Ring.id R) }
  let adj : Adjunction F G :=
    { unit := η, counit := ε, triangle_one := by rfl, triangle_two := by rfl, associativity := by rfl }
  exact adj.isRightAdjoint
